@Test
public void testAddToJobConfFromHCat() throws Exception {
    File hcatConfig = new File(OOZIE_HOME_DIR, "hcatConf.xml");
    Writer fw = new OutputStreamWriter(new FileOutputStream(hcatConfig), StandardCharsets.UTF_8);
